use std::{fs,path::Path};use serde_json::json;
fn main(){let root=Path::new("/tmp/zopro-isolated-grouping");let mut text=fs::read_to_string("/tmp/zopro-grouping-lower-bound/pipeline.rs").unwrap();let mut edits=Vec::new();let mut change=|old:&str,new:&str|{assert_eq!(text.matches(old).count(),1,"{old}");text=text.replacen(old,new,1);edits.push(json!({"before":old,"after":new}));};
 change("const ROOT:&str=\"/tmp/zopro-grouping-lower-bound\";","const ROOT:&str=\"/tmp/zopro-isolated-grouping\";");
 change("for f in [\"/tmp/zopro-ready-c7a/proof-inventory.json\",\"/tmp/zopro-stage-costs/proof-inventory.json\"]","for f in [\"/tmp/zopro-ready-c7a/proof-inventory.json\",\"/tmp/zopro-stage-costs/proof-inventory.json\",\"/tmp/zopro-grouping-lower-bound/proof-inventory.json\",\"/tmp/zopro-lower-bound-c7a/proof-inventory.json\"]");
 change("assert_eq!(prior.len(),5238)","assert_eq!(prior.len(),5612)");change("assert_eq!(prior.len(),5256)","assert_eq!(prior.len(),5630)");
 change("for rel in [\"pipeline.rs\",\"pipeline\",\"native-plan.json\",\"native/result.json\",\"native/on/artifacts.json\",\"native/on-core/stdout.log\",\"native/on-prover/stdout.log\"]","for rel in [\"pipeline.rs\",\"pipeline\",\"prepare-pipeline.rs\",\"pipeline-adaptation.json\",\"audit-current.rs\",\"audit-current/results.json\",\"codegen-review.json\",\"native-plan.json\",\"native/result.json\",\"native/on/artifacts.json\",\"native/on-core/stdout.log\",\"native/on-prover/stdout.log\"]");
 change("assert_eq!(read(r.join(\"native/result.json\"))[\"status\"],\"complete\");let artifact", "assert_eq!(read(r.join(\"native/result.json\"))[\"status\"],\"complete\");assert_eq!(read(r.join(\"codegen-review.json\"))[\"original_grouping_structure_preserved\"],true);assert_eq!(read(r.join(\"native/on-core/tests.json\"))[\"passed_tests\"].as_array().unwrap().len(),115);let artifact");
 change("else if candidate>1.02{regressions.push(format!(\"{name} ON/OFF={candidate}\"));}","if candidate>1.02{regressions.push(format!(\"{name} ON/OFF={candidate}\"));}if gm(&on_acc)>1.02{regressions.push(format!(\"{name} ON/accepted={}\",gm(&on_acc)));}");
 change("let adopt=calibration.is_empty()&&regressions.is_empty()&&primary_ratio<=0.98&&primary_wins>=2&&original_ratio<=0.995&&accepted_ratio<=0.995;", "let adopt=calibration.is_empty()&&regressions.is_empty()&&original_ratio<=1.00&&accepted_ratio<=1.00;");
 change("config[\"blocks\"]=json!(3);","for category in config[\"symbol_categories\"].as_array_mut().unwrap(){if category[\"name\"]==\"grouping\"{category[\"contains\"].as_array_mut().unwrap().push(json!(\"lower_bound\"));}}config[\"blocks\"]=json!(3);");
 drop(change);text=text.replace("adoption_gate_passed","local_qualification_passed").replace("prior5238","prior5612").replace("prior5256","prior5630").replace("adoptiongate","localqualification");fs::write(root.join("pipeline.rs"),text).unwrap();fs::write(root.join("pipeline-adaptation.json"),serde_json::to_vec_pretty(&edits).unwrap()).unwrap();}
